#!/bin/bash
step() { local name=$1; local dir=$2; shift 2; : > /workspace/rea-article/transcripts/$name.txt; for c in "$@"; do echo "\$ $c" >> /workspace/rea-article/transcripts/$name.txt; bash -c "source ~/.local/rea-env.sh; export GHIDRA_INSTALL_DIR=/workspace/ghidra/ghidra_12.1.4_PUBLIC; cd $dir; $c" >> /workspace/rea-article/transcripts/$name.txt 2>&1; echo >> /workspace/rea-article/transcripts/$name.txt; done; }
C=/workspace/re/crackme; L=/workspace/re/lab
step t08-trace $C "rea trace \$PWD/target/crackme 'Wrong password' --provider ghidra --json | jq -c '.evidence_id, .confidence, .normalized_result.matches[], (.normalized_result.references[] | {from: .source_address, in_function: .containing_procedure.procedure.address, name: .containing_procedure.procedure.name})'"
step t15-mcp-replay $C "jq -c '{tool: \"trace_feature\", evidence_id, confidence, match: .normalized_result.matches[0].value, refs: [.normalized_result.references[].source_address], in: .normalized_result.references[0].containing_procedure.procedure.name}' notes/mcp-trace-access-granted.json" "jq -c '{tool: \"annotate_native_function\", evidence_id, name: .normalized_result.annotations.name, comment: .normalized_result.annotations.comment}' notes/mcp-annotate.json" "jq -c '{exported: .records|length, unknowns: [.unknowns[]? | {unknown_id, status, severity, question}]}' notes/evidence.json"
step t16-js-electron $L "rea analyze-javascript-application \$PWD/jsapp --json > jsapp-evidence.json 2>/dev/null; jq -c '{evidence_id, confidence}' jsapp-evidence.json" "jq '.normalized_result.summary' jsapp-evidence.json"
step t17-js-ipc $L "jq -r '.normalized_result.graph.nodes[] | select(.kind != null) | [.kind, (.label // .name // .id)] | @tsv' jsapp-evidence.json | sort | uniq | head -30"
step t18-web $L "curl -s http://127.0.0.1:9333/json/version | jq -r .Browser" "rea list-browser-targets http://127.0.0.1:9333 --allowed-origins http://127.0.0.1:8765 --filter-output evidence_id,normalized_result.targets,normalized_result.excluded" "rea analyze-web-bundle http://127.0.0.1:9333 41DAC25A4D76D9793754752B1EEE9BC4 --allowed-origins http://127.0.0.1:8765 --observation-ms 1500 --json | jq -c '.evidence_id, (.normalized_result.observations.chunks.nodes[] | {url, bytes}), (.normalized_result.observations.chunks.edges[] | {kind, specifier, line: .location.line}), {endpoints: .normalized_result.observations.endpoints, routes: .normalized_result.observations.routes}, .normalized_result.completeness'"
step t19-evm $L "cat evm/demo-runtime.hex" "rea inspect-evm-interface \$PWD/evm/demo-runtime.hex hex --json | jq -c '.evidence_id, .normalized_result.evidence_kind, (.normalized_result.functions[]), {runtime_execution: .normalized_result.runtime_execution, discovery_completeness: .normalized_result.discovery_completeness}'"
step t20-go-main-only $L "rea inspect-go-binary \$PWD/go/hello --json 2>&1 | jq -c '{code, message}'"
